import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import {
  Container,
  Typography,
  Grid,
  Paper,
  Box,
  Chip,
  Divider,
  Card,
  CardContent,
  CardMedia,
} from '@mui/material';
import { Theme } from '@mui/material/styles';
import { SxProps } from '@mui/system';
import DetailHeaderNavi from './components/Nav/detailpageheader';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer
} from 'recharts';
import Papa from 'papaparse';

interface Volume {
  volume: number;
  releaseDate: string;
  coverImage: string;
  price: number;
  isbn: string;
  description: string;
  pages: number;
}

interface MangaDetail {
  title: string;
  volumes: Volume[];
  author: string;
  publisher: string;
  magazine: string;
  demographic: string;
  genres: string[];
  startDate: string;
}

const DetailPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const [mangaDetail, setMangaDetail] = useState<MangaDetail | null>(null);
  const [loading, setLoading] = useState(true);
  const title = searchParams.get('title');

  useEffect(() => {
    const fetchMangaDetail = async () => {
      try {
        const response = await fetch('/mangaDetails.json');
        const data = await response.json();
        const manga = data.manga.find((m: MangaDetail) => m.title === title);
        setMangaDetail(manga || null);
      } catch (error) {
        console.error('Error fetching manga details:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchMangaDetail();
  }, [title]);

  if (loading) {
    return (
      <Container>
        <Typography>Loading...</Typography>
      </Container>
    );
  }

  if (!mangaDetail) {
    return (
      <Container>
        <Typography color="error">漫画が見つかりませんでした。</Typography>
      </Container>
    );
  }

  return (
    <>
      <DetailHeaderNavi />
      <Container>
        <Box sx={{ py: 4 }}>
          {/* 基本情報 */}
          <Paper elevation={0} sx={{ p: 3, mb: 4, backgroundColor: '#f8f9fa', borderRadius: 2 }}>
            <Typography variant="h4" component="h1" gutterBottom sx={{ fontWeight: 'bold' }}>
              {mangaDetail.title}
            </Typography>
            <Box sx={{ mb: 2 }}>
              {mangaDetail.genres.map((genre) => (
                <Chip
                  key={genre}
                  label={genre}
                  sx={{ mr: 1, mb: 1, backgroundColor: '#009879', color: 'white' }}
                />
              ))}
            </Box>
            <Grid container spacing={2} sx={{ mt: 2 }}>
                <Typography variant="body1" sx={{ mb: 1 }}>
                  <strong>作者：</strong> {mangaDetail.author}
                </Typography>
                <Typography variant="body1" sx={{ mb: 1 }}>
                  <strong>出版社：</strong> {mangaDetail.publisher}
                </Typography>
                <Typography variant="body1" sx={{ mb: 1 }}>
                  <strong>掲載誌：</strong> {mangaDetail.magazine}
                </Typography>
                <Typography variant="body1" sx={{ mb: 1 }}>
                  <strong>ジャンル：</strong> {mangaDetail.demographic}
                </Typography>
                <Typography variant="body1">
                  <strong>連載開始：</strong> {new Date(mangaDetail.startDate).toLocaleDateString('ja-JP')}
                </Typography>
            </Grid>
          </Paper>

          {/* 単行本リスト */}
          <Typography variant="h5" component="h2" gutterBottom sx={{ mb: 3, fontWeight: 'bold' }}>
            単行本一覧
          </Typography>
          <Grid container spacing={3}>
            {mangaDetail.volumes.map((volume) => (
                <Card sx={{ 
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  transition: 'transform 0.3s ease-in-out',
                  '&:hover': {
                    transform: 'translateY(-8px)'
                  }
                }}>
                  <CardMedia
                    component="img"
                    height="300"
                    image={volume.coverImage}
                    alt={`${mangaDetail.title} 第${volume.volume}巻`}
                    sx={{ objectFit: 'cover' }}
                  />
                  <CardContent>
                    <Typography variant="h6" gutterBottom>
                      第{volume.volume}巻
                    </Typography>
                    <Typography variant="body2" color="text.secondary" paragraph>
                      {volume.description}
                    </Typography>
                    <Divider sx={{ my: 1 }} />
                    <Typography variant="body2" color="text.secondary">
                      発売日: {new Date(volume.releaseDate).toLocaleDateString('ja-JP')}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      価格: ¥{volume.price.toLocaleString()}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      ページ数: {volume.pages}ページ
                    </Typography>
                  </CardContent>
                </Card>
            ))}
          </Grid>
        </Box>
      </Container>
    </>
  );
}
export default DetailPage;
